import java.util.*;

class Solution {
    public int cheapestWalk(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int[] dp = new int[cols];                  // dp[c] = cheapest cost to reach (r, c)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (r == 0 && c == 0) { dp[c] = grid[0][0]; continue; }
                int from = Integer.MAX_VALUE;
                if (r > 0) from = dp[c];                       // from above
                if (c > 0) from = Math.min(from, dp[c - 1]);   // from the left
                dp[c] = grid[r][c] + from;
            }
        }
        return dp[cols - 1];
    }
}

