class Solution:
    def cheapestWalk(self, grid: List[List[int]]) -> int:
        cols = len(grid[0]); d = [inf] * cols; d[0] = 0
        for row in grid:
            d[0] += row[0]
            for c in range(1, cols):
                d[c] = row[c] + min(d[c], d[c - 1])
        return d[-1]

