function cheapestWalk(grid) {
  const C = grid[0].length, d = new Array(C).fill(Infinity); d[0] = 0;
  for (const row of grid) { d[0] += row[0]; for (let c = 1; c < C; c++) d[c] = row[c] + Math.min(d[c], d[c - 1]); }
  return d[C - 1];
}
